     1→"use client";
     2→
     3→import { useState, useEffect, useCallback } from "react";
     4→import { TeamMember } from "../types";
     5→import { Badge } from "./ui";
     6→import { useUnreadStore } from "../store/unreadStore";
     7→import { useSocket } from "../hooks/useSocket";
     8→import { useUnreadCount } from "../hooks/useUnreadCount";
     9→import { getAvatarUrl } from "@/lib/avatar";
    10→
    11→interface DirectMessagesProps {
    12→  members?: TeamMember[];
    13→  currentUserId?: string;
    14→  selectedDirectMessageId?: string;
    15→  onStartChat?: (memberId: string, dmConversationId?: string) => void;
    16→  onNewChat?: () => void;
    17→}
    18→
    19→interface ActiveDMConversation {
    20→  conversationId: string;
    21→  lastMessageAt: string;
    22→  createdAt: string;
    23→  otherUser: {
    24→    id: string;
    25→    email: string;
    26→    displayName: string;
    27→    realName?: string;
    28→    avatarUrl?: string;
    29→    isOnline: boolean;
    30→    lastSeenAt?: string;
    31→    isStarred?: boolean;
    32→  };
    33→  unreadCount: number;
    34→  lastReadAt?: string;
    35→  lastMessage?: {
    36→    id: string;
    37→    content: string;
    38→    createdAt: string;
    39→    user: {
    40→      id: string;
    41→      displayName: string;
    42→      avatarUrl?: string;
    43→    };
    44→  };
    45→  messageCount: number;
    46→}
    47→
    48→export default function DirectMessages({
    49→  members = [], // Not used, but kept for interface compatibility
    50→  currentUserId,
    51→  selectedDirectMessageId,
    52→  onStartChat,
    53→  onNewChat, // Not used, but kept for interface compatibility
    54→}: DirectMessagesProps) {
    55→  const [searchQuery, setSearchQuery] = useState("");
    56→  const [searchResults, setSearchResults] = useState<TeamMember[]>([]);
    57→  const [isSearching, setIsSearching] = useState(false);
    58→  const [activeConversations, setActiveConversations] = useState<
    59→    ActiveDMConversation[]
    60→  >([]);
    61→  const [starredUsers, setStarredUsers] = useState<TeamMember[]>([]);
    62→  const [isLoading, setIsLoading] = useState(true);
    63→  const { getUnreadCount } = useUnreadStore();
    64→  const { socket } = useSocket();
    65→  const { markAsRead } = useUnreadCount();
    66→
    67→  // Load active DM conversations and starred users
    68→  useEffect(() => {
    69→    const loadActiveConversations = async () => {
    70→      setIsLoading(true);
    71→      try {
    72→        const response = await fetch("/api/conversations/dm/active", {
    73→          credentials: "include",
    74→        });
    75→
    76→        if (response.ok) {
    77→          const data = await response.json();
    78→          setActiveConversations(data.conversations || []);
    79→        }
    80→      } catch (error) {
    81→        console.error("Error loading active conversations:", error);
    82→      } finally {
    83→        setIsLoading(false);
    84→      }
    85→    };
    86→
    87→    const loadStarredUsers = async () => {
    88→      try {
    89→        const response = await fetch("/api/users/starred", {
    90→          credentials: "include",
    91→        });
    92→
    93→        if (response.ok) {
    94→          const data = await response.json();
    95→          setStarredUsers(data.users || []);
    96→        }
    97→      } catch (error) {
    98→        console.error("Error loading starred users:", error);
    99→      }
   100→    };
   101→
   102→    loadActiveConversations();
   103→    loadStarredUsers();
   104→
   105→    // Listen for WebSocket events to update active conversation list in real-time
   106→    const handleActiveConversationsUpdate = () => {
   107→      // Refresh active conversation list
   108→      loadActiveConversations();
   109→    };
   110→
   111→    // Listen for starred users update events
   112→    const handleStarredUsersUpdate = () => {
   113→      loadStarredUsers();
   114→    };
   115→
   116→    // Listen to events via socket
   117→    if (socket) {
   118→      socket.on("active-conversations-update", handleActiveConversationsUpdate);
   119→    }
   120→
   121→    // Listen for custom events
   122→    window.addEventListener("starred-users-updated", handleStarredUsersUpdate);
   123→
   124→    // Cleanup function
   125→    return () => {
   126→      if (socket) {
   127→        socket.off(
   128→          "active-conversations-update",
   129→          handleActiveConversationsUpdate,
   130→        );
   131→      }
   132→      window.removeEventListener(
   133→        "starred-users-updated",
   134→        handleStarredUsersUpdate,
   135→      );
   136→    };
   137→  }, [socket]);
   138→
   139→  // Handle starting a chat (adds conversation to list immediately)
   140→  const handleStartChat = useCallback(
   141→    async (userId: string, dmConversationId?: string) => {
   142→      // === Step 1: Clear search query, switching to active conversation list ===
   143→      if (searchQuery.trim()) {
   144→        setSearchQuery("");
   145→        console.log(
   146→          "🔍 [DEBUG] Clear search query, switching to active conversation list",
   147→        );
   148→      }
   149→
   150→      // If dmConversationId already exists, use it directly
   151→      if (dmConversationId) {
   152→        // When clicking to enter conversation, automatically clear unread count
   153→        try {
   154→          await markAsRead(undefined, dmConversationId);
   155→        } catch (error) {
   156→          console.error("Failed to mark as read:", error);
   157→        }
   158→        onStartChat?.(userId, dmConversationId);
   159→        return;
   160→      }
   161→
   162→      // Otherwise, create or get conversation
   163→      try {
   164→        const response = await fetch("/api/conversations/dm", {
   165→          method: "POST",
   166→          headers: {
   167→            "Content-Type": "application/json",
   168→          },
   169→          credentials: "include",
   170→          body: JSON.stringify({ userId }),
   171→        });
   172→
   173→        if (response.ok) {
   174→          const conversation = await response.json();
   175→          const otherMember = conversation.members.find(
   176→            (m: any) => m.userId !== currentUserId,
   177→          );
   178→
   179→          // Ensure otherMember exists
   180→          if (!otherMember?.user?.id) {
   181→            throw new Error("Failed to find other user");
   182→          }
   183→
   184→          const newConversation: ActiveDMConversation = {
   185→            conversationId: conversation.id,
   186→            lastMessageAt: "",
   187→            createdAt: conversation.createdAt,
   188→            otherUser: {
   189→              id: otherMember.user.id,
   190→              email: otherMember.user.email,
   191→              displayName: otherMember.user.displayName,
   192→              realName: otherMember.user.realName,
   193→              avatarUrl: otherMember.user.avatarUrl,
   194→              isOnline: otherMember.user.isOnline,
   195→              lastSeenAt: otherMember.user.lastSeenAt,
   196→            },
   197→            unreadCount: 0,
   198→            lastReadAt: undefined,
   199→            lastMessage: undefined,
   200→            messageCount: 0,
   201→          };
   202→
   203→          // Optimistic update: add new conversation to top of list
   204→          setActiveConversations((prev) => {
   205→            // Check if already exists
   206→            if (prev.some((conv) => conv.conversationId === conversation.id)) {
   207→              return prev;
   208→            }
   209→            return [newConversation, ...prev];
   210→          });
   211→
   212→          // Notify WebSocket to update
   213→          if (socket) {
   214→            socket.emit("active-conversations-update", {
   215→              dmConversationId: conversation.id,
   216→            });
   217→          }
   218→
   219→          onStartChat?.(userId, conversation.id);
   220→        } else {
   221→          // Even if it fails, call the original callback
   222→          onStartChat?.(userId);
   223→        }
   224→      } catch (error) {
   225→        console.error("Error starting chat:", error);
   226→        onStartChat?.(userId);
   227→      }
   228→    },
   229→    [socket, onStartChat, currentUserId, searchQuery],
   230→  );
   231→
   232→  // Search team members (searches all users, not just active ones)
   233→  useEffect(() => {
   234→    const searchMembers = async () => {
   235→      if (!searchQuery.trim()) {
   236→        setSearchResults([]);
   237→        setIsSearching(false);
   238→        return;
   239→      }
   240→
   241→      setIsSearching(true);
   242→      try {
   243→        const response = await fetch(
   244→          `/api/users/search?q=${encodeURIComponent(searchQuery)}`,
   245→          {
   246→            credentials: "include",
   247→          },
   248→        );
   249→
   250→        if (response.ok) {
   251→          const data = await response.json();
   252→          setSearchResults(data.users || []);
   253→        }
   254→      } catch (error) {
   255→        console.error("Error searching members:", error);
   256→      } finally {
   257→        setIsSearching(false);
   258→      }
   259→    };
   260→
   261→    const timeoutId = setTimeout(searchMembers, 300);
   262→    return () => clearTimeout(timeoutId);
   263→  }, [searchQuery]);
   264→
   265→  // Show search results or active conversations
   266→  const displayConversations = searchQuery.trim()
   267→    ? searchResults.map((user) => ({
   268→        conversationId: user.dmConversationId || "", // Search results don't have conversationId, leave empty for handleStartChat to create
   269→        lastMessageAt: "",
   270→        createdAt: "",
   271→        otherUser: {
   272→          id: user.id,
   273→          email: user.email,
   274→          displayName: user.displayName,
   275→          realName: user.realName,
   276→          avatarUrl: user.avatarUrl,
   277→          isOnline: user.isOnline,
   278→          lastSeenAt: user.lastSeenAt,
   279→        },
   280→        unreadCount: user.unreadCount || 0,
   281→        lastReadAt: user.lastReadAt,
   282→        lastMessage: null,
   283→        messageCount: 0,
   284→      }))
   285→    : activeConversations.filter(
   286→        (conv) =>
   287→          // Filter out users already in starred list to avoid duplicate display
   288→          !starredUsers.some(
   289→            (starredUser) => starredUser.id === conv.otherUser.id,
   290→          ),
   291→      );
   292→
   293→  const getStatusIndicator = (isOnline: boolean) => {
   294→    if (isOnline) {
   295→      return (
   296→        <span className="absolute bottom-0 right-0 block h-2 w-2 rounded-full bg-green-500" />
   297→      );
   298→    }
   299→    return (
   300→      <span className="absolute bottom-0 right-0 block h-2 w-2 rounded-full border border-gray-400 bg-transparent" />
   301→    );
   302→  };
   303→
   304→  return (
   305→    <div className="mb-4">
   306→      {/* Header */}
   307→      <div
   308→        className="flex items-center justify-between px-3 py-2 hover:bg-white/10 cursor-pointer"
   309→        onClick={() => setSearchQuery("")}
   310→      >
   311→        <h3 className="text-white/80 text-sm font-medium tracking-wide uppercase">
   312→          DIRECT MESSAGES
   313→        </h3>
   314→        <button
   315→          className="text-white/60 hover:text-white transition-colors"
   316→          aria-label="Search members"
   317→          title="Search members"
   318→          onClick={(e) => {
   319→            e.stopPropagation();
   320→            setSearchQuery("");
   321→          }}
   322→        >
   323→          <svg
   324→            xmlns="http://www.w3.org/2000/svg"
   325→            fill="none"
   326→            viewBox="0 0 24 24"
   327→            strokeWidth={2.5}
   328→            stroke="currentColor"
   329→            className="w-5 h-5"
   330→          >
   331→            <path
   332→              strokeLinecap="round"
   333→              strokeLinejoin="round"
   334→              d="M21 21l-4.35-4.35m0 0A7.5 7.5 0 1010.5 18a7.5 7.5 0 006.15-3.35z"
   335→            />
   336→          </svg>
   337→        </button>
   338→      </div>
   339→
   340→      {/* Search box */}
   341→      <div className="px-3 py-2">
   342→        <input
   343→          type="text"
   344→          value={searchQuery}
   345→          onChange={(e) => setSearchQuery(e.target.value)}
   346→          placeholder="Search members..."
   347→          className="w-full px-3 py-1.5 bg-white/10 text-white text-sm rounded border-none outline-none placeholder-white/50"
   348→          autoFocus
   349→        />
   350→      </div>
   351→
   352→      {/* Starred users group - only show in non-search mode */}
   353→      {!searchQuery && starredUsers.length > 0 && (
   354→        <div className="mb-2">
   355→          <div className="px-3 py-1.5">
   356→            <h4 className="text-white/60 text-xs font-medium tracking-wide uppercase">
   357→              STARRED
   358→            </h4>
   359→          </div>
   360→          <div className="space-y-0.5">
   361→            {starredUsers.map((user) => {
   362→              const isSelected = selectedDirectMessageId === user.id;
   363→              const conversationId = user.dmConversationId || user.id;
   364→              const realUnreadCount = getUnreadCount(conversationId);
   365→              const hasUnread = realUnreadCount > 0;
   366→
   367→              // Defensive check: only show unread badge when unread count > 0 and last message was not sent by current user
   368→              // Note: Starred list has no lastMessage info, but getUnreadCount already excludes the sender
   369→              const shouldShowUnreadBadge = hasUnread;
   370→
   371→              return (
   372→                <div
   373→                  key={conversationId}
   374→                  className={`flex items-center px-3 py-1.5 mx-2 rounded cursor-pointer transition-colors group ${
   375→                    isSelected ? "bg-[#1164A3] text-white" : "hover:bg-white/10"
   376→                  }`}
   377→                  onClick={() => handleStartChat(user.id, conversationId)}
   378→                >
   379→                  {/* Avatar with status indicator */}
   380→                  <div className="relative flex-shrink-0">
   381→                    <img
   382→                      src={getAvatarUrl(user.avatarUrl, user, 24)}
   383→                      alt={user.displayName}
   384→                      className="w-5 h-5 rounded-sm"
   385→                      style={{ borderRadius: "4px" }}
   386→                    />
   387→                    {getStatusIndicator(user.isOnline)}
   388→                  </div>
   389→
   390→                  {/* Display Name with Star Icon */}
   391→                  <span
   392→                    className={`ml-3 text-sm truncate transition-colors ${
   393→                      isSelected
   394→                        ? "text-white"
   395→                        : "text-white/80 group-hover:text-white"
   396→                    }`}
   397→                  >
   398→                    {user.displayName}
   399→                  </span>
   400→
   401→                  {/* Yellow Star Icon */}
   402→                  <svg
   403→                    xmlns="http://www.w3.org/2000/svg"
   404→                    fill="#FFD700"
   405→                    viewBox="0 0 24 24"
   406→                    className="w-4 h-4 ml-2 flex-shrink-0"
   407→                  >
   408→                    <path d="M11.48 3.499a.562.562 0 011.04 0l2.125 5.111a.563.563 0 00.475.345l5.518.442c.499.04.701.659.446 1.004l-1.348 1.867a.562.562 0 00-.146.353l-.36 3.178a.563.563 0 01-.611.43l-2.612-.642a.563.563 0 00-.465.316l-1.82 2.165a.562.562 0 01-.857-.348l.109-3.181a.563.563 0 00-.19-.458l-1.867-1.348a.563.563 0 00-.353-.146l-3.178-.36a.563.563 0 01-.43-.611l.642-2.612a.563.563 0 00-.316-.465l-2.165-1.82a.562.562 0 01.348-.857l3.181.109a.563.563 0 00.458-.19l1.348-1.867z" />
   409→                  </svg>
   410→
   411→                  {/* Unread Count Badge */}
   412→                  {shouldShowUnreadBadge && (
   413→                    <Badge
   414→                      count={realUnreadCount}
   415→                      size="sm"
   416→                      className="ml-auto"
   417→                    />
   418→                  )}
   419→                </div>
   420→              );
   421→            })}
   422→          </div>
   423→        </div>
   424→      )}
   425→
   426→      {/* All users group */}
   427→      <div>
   428→        <div className="px-3 py-1.5">
   429→          <h4 className="text-white/60 text-xs font-medium tracking-wide uppercase">
   430→            {searchQuery ? "Search Results" : "DIRECT MESSAGES"}
   431→          </h4>
   432→        </div>
   433→        <div className="space-y-0.5">
   434→          {displayConversations.map((conversation) => {
   435→            const otherUser = conversation.otherUser;
   436→            const isSelected = selectedDirectMessageId === otherUser.id;
   437→            const isCurrentUser = otherUser.id === currentUserId;
   438→            const conversationId = conversation.conversationId;
   439→            const unreadCount =
   440→              conversation.unreadCount || getUnreadCount(conversationId);
   441→            const hasUnread = unreadCount > 0;
   442→
   443→            // Defensive check: only show unread badge when unread count > 0 and last message was not sent by current user
   444→            // This ensures user-sent messages don't trigger their own notification badge
   445→            const shouldShowUnreadBadge =
   446→              hasUnread &&
   447→              (!conversation.lastMessage ||
   448→                conversation.lastMessage.user.id !== currentUserId);
   449→
   450→            return (
   451→              <div
   452→                key={conversationId}
   453→                className={`flex items-center px-3 py-1.5 mx-2 rounded cursor-pointer transition-colors group ${
   454→                  isSelected ? "bg-[#1164A3] text-white" : "hover:bg-white/10"
   455→                }`}
   456→                onClick={() => handleStartChat(otherUser.id, conversationId)}
   457→              >
   458→                {/* Avatar with status indicator */}
   459→                <div className="relative flex-shrink-0">
   460→                  <img
   461→                    src={getAvatarUrl(otherUser.avatarUrl, otherUser, 24)}
   462→                    alt={otherUser.displayName}
   463→                    className="w-5 h-5 rounded-sm"
   464→                    style={{ borderRadius: "4px" }}
   465→                  />
   466→                  {getStatusIndicator(otherUser.isOnline)}
   467→                </div>
   468→
   469→                {/* Display Name */}
   470→                <span
   471→                  className={`ml-3 text-sm truncate transition-colors ${
   472→                    isSelected
   473→                      ? "text-white"
   474→                      : shouldShowUnreadBadge
   475→                        ? "text-white font-semibold"
   476→                        : "text-white/80 group-hover:text-white"
   477→                  }`}
   478→                >
   479→                  {otherUser.displayName}
   480→                  {isCurrentUser ? " (you)" : ""}
   481→                </span>
   482→
   483→                {/* Unread Count Badge */}
   484→                {shouldShowUnreadBadge && (
   485→                  <Badge count={unreadCount} size="sm" className="ml-auto" />
   486→                )}
   487→              </div>
   488→            );
   489→          })}
   490→        </div>
   491→      </div>
   492→
   493→      {/* Empty state */}
   494→      {displayConversations.length === 0 &&
   495→        !isSearching &&
   496→        !searchQuery &&
   497→        !isLoading && (
   498→          <div className="px-3 py-2 text-white/50 text-sm">
   499→            No direct messages yet.
   500→          </div>
   501→        )}
   502→
   503→      {/* Loading state */}
   504→      {isLoading && (
   505→        <div className="px-3 py-2 text-white/50 text-sm">Loading...</div>
   506→      )}
   507→
   508→      {/* Search no results */}
   509→      {displayConversations.length === 0 && searchQuery && !isSearching && (
   510→        <div className="px-3 py-2 text-white/50 text-sm">
   511→          User "{searchQuery}" not found
   512→        </div>
   513→      )}
   514→
   515→      {/* Searching state */}
   516→      {isSearching && (
   517→        <div className="px-3 py-2 text-white/50 text-sm">Searching...</div>
   518→      )}
   519→    </div>
   520→  );
   521→}
