"use client";

import { useState } from "react";
import { Channel } from "../types/channel";
import { Badge } from "./ui";
import { useUnreadStore } from "../store/unreadStore";
import CreateChannelModal from "./CreateChannelModal";

interface ChannelsProps {
  channels?: Channel[];
  selectedChannelId?: string;
  joinedChannels?: string[];
  onSelectChannel?: (channelId: string) => void;
  onCreateChannel?: (channel: Channel) => void;
  onBrowseChannels?: () => void;
}

export default function Channels({
  channels = [],
  selectedChannelId,
  joinedChannels = [],
  onSelectChannel,
  onCreateChannel,
  onBrowseChannels,
}: ChannelsProps) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { getUnreadCount } = useUnreadStore();

  const handleCreateChannel = () => {
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const handleCreateChannelSubmit = async (
    channelName: string,
    description?: string,
    isPrivate?: boolean,
  ) => {
    try {
      // Call actual API to create channel
      const response = await fetch("/api/channels", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include",
        body: JSON.stringify({
          name: channelName,
          description,
          isPrivate: isPrivate || false,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "Failed to create channel");
      }

      const data = await response.json();
      const newChannel = data.channel;

      // Notify parent component
      onCreateChannel?.(newChannel);

      // Close modal
      setIsModalOpen(false);

      // Auto-select newly created channel (using real ID)
      onSelectChannel?.(newChannel.id);

      console.log("Created new channel successfully:", newChannel);
    } catch (error) {
      console.error("Create channel error:", error);
      // Can add user-friendly error message
      alert(
        `Failed to create channel: ${error instanceof Error ? error.message : "Unknown error"}`,
      );
    }
  };

  // Only show joined channels
  const joinedChannelsList = channels.filter((channel) =>
    joinedChannels.includes(channel.id),
  );

  return (
    <div className="mb-4">
      {/* Header */}
      <div
        className="flex items-center justify-between px-3 py-2 hover:bg-white/10 cursor-pointer"
        onClick={handleCreateChannel}
      >
        <h3 className="text-white/80 text-sm font-medium tracking-wide uppercase">
          Channels
        </h3>
        <div className="flex items-center gap-1">
          <button
            className="text-white/60 hover:text-white transition-colors p-1"
            aria-label="Browse channels"
            title="Browse channels"
            onClick={(e) => {
              e.stopPropagation();
              onBrowseChannels?.();
            }}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={1.5}
              stroke="currentColor"
              className="w-4 h-4"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M3.75 5.25h16.5m-16.5 4.5h16.5m-16.5 4.5h16.5m-16.5 4.5h16.5"
              />
            </svg>
          </button>
          <button
            className="text-white/60 hover:text-white transition-colors"
            aria-label="Create new channel"
            title="Create new channel"
            onClick={(e) => {
              e.stopPropagation();
              handleCreateChannel();
            }}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth={2.5}
              stroke="currentColor"
              className="w-5 h-5"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M12 4.5v15m7.5-7.5h-15"
              />
            </svg>
          </button>
        </div>
      </div>

      {/* Channels List */}
      <div className="space-y-0.5">
        {joinedChannelsList.map((channel) => {
          const unreadCount = getUnreadCount(channel.id);
          const hasUnread = unreadCount > 0;
          const isSelected = selectedChannelId === channel.id;

          return (
            <div
              key={channel.id}
              className={`flex items-center px-3 py-1.5 mx-2 rounded cursor-pointer transition-colors group ${
                isSelected ? "bg-slack-blue text-white" : "hover:bg-white/10"
              }`}
              onClick={() => onSelectChannel?.(channel.id)}
            >
              {/* Channel Icon */}
              <span
                className={`text-base font-medium ${
                  isSelected
                    ? "text-white"
                    : "text-white/70 group-hover:text-white"
                } transition-colors`}
              >
                #
              </span>

              {/* Channel Name */}
              <span
                className={`ml-3 text-sm truncate transition-colors ${
                  isSelected
                    ? "text-white"
                    : hasUnread
                      ? "text-white font-semibold"
                      : "text-white/70 group-hover:text-white"
                }`}
              >
                {channel.name}
              </span>

              {/* Unread Count Badge */}
              {hasUnread && (
                <Badge count={unreadCount} size="sm" className="ml-auto" />
              )}
            </div>
          );
        })}
      </div>

      {/* Empty state */}
      {joinedChannelsList.length === 0 && (
        <div className="px-3 py-2 text-white/50 text-sm">
          No joined channels
        </div>
      )}

      {/* Create channel modal */}
      <CreateChannelModal
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        onCreate={handleCreateChannelSubmit}
      />
    </div>
  );
}

