    74→          setJoinedChannels(joined);
    75→
    76→          // If no channel is selected, select the first joined channel
    77→          if (!selectedChannel && joined.length > 0) {
    78→            setSelectedChannel(joined[0]);
    79→          }
    80→        }
    81→      } catch (error) {
    82→        console.error('Error fetching channels:', error);
    83→      }
    84→    };
    85→
    86→    if (user) {
    87→      fetchChannels();
    88→    }
    89→  }, [user, selectedChannel]);
    90→
    91→  // Get user data
    92→  useEffect(() => {
    93→    const fetchUsers = async () => {
    94→      try {
    95→        const response = await fetch('/api/users', {
    96→          credentials: 'include'
    97→        });
    98→
    99→        if (response.ok) {
   100→          const data = await response.json();
   101→          setUsers(data.users);
   102→        }
   103→      } catch (error) {
   104→        console.error('Error fetching users:', error);
   105→      }
