   110→    }
   111→  }, [user]);
   112→
   113→  // Listen for route changes and sync state
   114→  useEffect(() => {
   115→    if (userId && users.length > 0) {
   116→      const member = users.find(u => u.id === userId);
   117→      if (member) {
   118→        setSelectedChat(userId);
   119→        setSelectedChannel(undefined);
   120→        setCurrentView('channel');
   121→        console.log('🔄 [DEBUG] Route state sync - switching to DM:', userId);
   122→      }
   123→    } else if (!userId) {
   124→      // If no userId parameter and currently in DM mode, switch back to channel mode
   125→      if (selectedChat) {
   126→        setSelectedChat(undefined);
