   141→      if (joinedChannels.includes(channelParam)) {
   142→        setSelectedChannel(channelParam);
   143→        setSelectedChat(undefined);
   144→        setCurrentView('channel');
   145→        console.log('✅ [DEBUG] Channel selected:', channelParam);
   146→      } else {
   147→        console.log('⚠️ [DEBUG] Channel not joined or does not exist:', channelParam);
   148→      }
   149→    }
   150→
   151→    if (viewParam === 'browse') {
   152→      setCurrentView('browse');
   153→      setSelectedChat(undefined);
   154→      console.log('🔍 [DEBUG] Switching to browse channels view');
   155→    }
   156→  }, [joinedChannels]);
   157→
   158→  useEffect(() => {
   159→    if (!loading && !user) {
   160→      router.push('/login');
   161→    }
   162→  }, [user, loading, router]);
   163→
   164→  const handleLogout = async () => {
   165→    try {
   166→      await logout();
   167→      router.push('/login');
   168→    } catch (err) {
   169→      console.error('Logout failed:', err);
   170→    }
   171→  };
   172→
   173→  const handleStartChat = async (memberId: string, dmConversationId?: string) => {
   174→    try {
   175→      // === Step 1: Immediate optimistic update ===
   176→      // Update selected DM state and highlight immediately
   177→      setSelectedChat(memberId);
   178→      // Clear selected channel
   179→      setSelectedChannel(undefined);
   180→
   181→      // === Step 2: Immediate page navigation ===
