   183→      const targetUrl = `/dm/${memberId}`;
   184→      router.push(targetUrl);
   185→
   186→      // === Step 3: Create/get conversation in background (non-blocking) ===
   187→      // If conversationId is not provided, create or get DM conversation
   188→      if (!dmConversationId) {
   189→        const createConversation = async () => {
   190→          try {
   191→            const resp = await fetch('/api/conversations/dm', {
   192→              method: 'POST',
