    17→
    18→interface DirectMessageViewProps {
    19→  member: TeamMember;
    20→  currentUserId: string;
    21→}
    22→
    23→export default function DirectMessageView({
    24→  member,
    25→  currentUserId,
    26→}: DirectMessageViewProps) {
    27→  const isOwnSpace = member.id === currentUserId;
    28→  const [messages, setMessages] = useState<Message[]>([]);
    29→  const [conversation, setConversation] = useState<DMConversation | null>(null);
    30→  const [isLoading, setIsLoading] = useState(true);
    31→  const [isLoadingMore, setIsLoadingMore] = useState(false);
    32→  const [hasMore, setHasMore] = useState(true);
    33→  const [error, setError] = useState<string | null>(null);
    34→  const [activeTab, setActiveTab] = useState<
    35→    "messages" | "canvas" | "files" | "shared"
    36→  >("messages");
    37→  const { markAsRead } = useUnreadCount();
    38→  const { socket, isConnected, connect, connectionStatus } = useSocket();
    39→  const messageListRef = useRef<MessageListRef>(null);
    40→
    41→  // Thread state management
    42→  const {
    43→    setActiveThread,
    44→    activeThreadId,
    45→    activeThreadMessage,
    46→    threadPanelOpen,
    47→    closeThread,
    48→  } = useThreadStore();
    49→
    50→  // Quoted message state
    51→  const [quotedMessage, setQuotedMessage] = useState<Message | null>(null);
    52→
    53→  // Input height state
    54→  const [inputHeight, setInputHeight] = useState(180); // Default height - increased to show all buttons
    55→  const [isResizingInput, setIsResizingInput] = useState(false);
    56→  const inputDragStart = useRef({ y: 0, height: 180 });
    57→
    58→  // Input drag handling
    59→  const handleInputDragStart = (e: React.MouseEvent) => {
    60→    setIsResizingInput(true);
    61→    inputDragStart.current = { y: e.clientY, height: inputHeight };
    62→  };
    63→
    64→  useEffect(() => {
    65→    const handleInputDrag = (e: MouseEvent) => {
    66→      if (!isResizingInput) return;
    67→      const deltaY = inputDragStart.current.y - e.clientY; // Increase height when dragging up
    68→      const newHeight = Math.max(
    69→        60,
    70→        Math.min(400, inputDragStart.current.height + deltaY),
    71→      );
    72→      setInputHeight(newHeight);
    73→    };
    74→
    75→    const handleInputDragEnd = () => {
    76→      setIsResizingInput(false);
    77→    };
    78→
    79→    if (isResizingInput) {
    80→      document.addEventListener("mousemove", handleInputDrag);
    81→      document.addEventListener("mouseup", handleInputDragEnd);
    82→      document.body.style.cursor = "row-resize";
    83→      document.body.style.userSelect = "none";
    84→    }
    85→
    86→    return () => {
    87→      document.removeEventListener("mousemove", handleInputDrag);
    88→      document.removeEventListener("mouseup", handleInputDragEnd);
    89→      document.body.style.cursor = "";
    90→      document.body.style.userSelect = "";
    91→    };
    92→  }, [isResizingInput]);
    93→
    94→  // Handle quoted message
    95→  const handleQuote = useCallback((message: Message) => {
    96→    setQuotedMessage(message);
    97→  }, []);
    98→
    99→  // Clear quoted message
   100→  const handleClearQuote = useCallback(() => {
   101→    setQuotedMessage(null);
   102→  }, []);
   103→
   104→  // Track if at bottom of message list
   105→  const isAtBottomRef = useRef(true);
   106→
   107→  // Listen for messageId parameter in URL for deep linking
   108→  useEffect(() => {
   109→    const urlParams = new URLSearchParams(window.location.search);
   110→    const messageId = urlParams.get("messageId");
   111→
   112→    if (messageId) {
   113→      // Add retry mechanism for when messageListRef is not ready yet
   114→      const highlightWithRetry = (retries = 10) => {
   115→        if (messageListRef.current) {
   116→          messageListRef.current.highlightMessage(messageId);
   117→
   118→          // Clear messageId parameter from URL to avoid duplicate highlight on refresh
   119→          const newUrl =
   120→            window.location.pathname +
   121→            window.location.search.replace(/[?&]messageId=[^&]*/, "");
   122→          window.history.replaceState({}, "", newUrl);
   123→        } else if (retries > 0) {
   124→          // Retry after a short delay
   125→          setTimeout(() => highlightWithRetry(retries - 1), 200);
   126→        }
   127→      };
   128→
   129→      highlightWithRetry();
   130→    }
   131→  }, [member.id]);
   132→
   133→  // Listen for search-navigate-to-message event from GlobalSearchModal
   134→  useEffect(() => {
   135→    const handleSearchNavigate = (e: Event) => {
   136→      const detail = (e as CustomEvent).detail;
   137→      if (!detail?.messageId || !messageListRef.current) return;
   138→
   139→      const highlightWithRetry = (retries = 10) => {
   140→        if (messageListRef.current) {
   141→          messageListRef.current.highlightMessage(detail.messageId);
   142→        } else if (retries > 0) {
   143→          setTimeout(() => highlightWithRetry(retries - 1), 200);
   144→        }
   145→      };
   146→
   147→      highlightWithRetry();
   148→    };
   149→
   150→    window.addEventListener("search-navigate-to-message", handleSearchNavigate);
   151→    return () => {
   152→      window.removeEventListener("search-navigate-to-message", handleSearchNavigate);
   153→    };
   154→  }, []);
   155→
   156→  // Force connect WebSocket (if not connected)
   157→  useEffect(() => {
   158→    console.log(`🔌 [DirectMessageView] WebSocket Status Check:`, {
   159→      socketExists: !!socket,
   160→      isConnected,
   161→      socketId: socket?.id,
   162→    });
   163→
   164→    if (!socket || !isConnected) {
   165→      console.log(`🔌 [DirectMessageView] Force connecting WebSocket...`);
   166→      connect();
   167→    }
   168→  }, [socket, isConnected, connect]);
   169→
   170→  // Handle scroll position change
   171→  const handleScrollPositionChange = (isAtBottom: boolean) => {
   172→    isAtBottomRef.current = isAtBottom;
   173→  };
   174→
   175→  // Handle thread reply
   176→  const handleThreadReply = useCallback(
   177→    (message: Message) => {
   178→      // Set active thread and open thread panel
   179→      setActiveThread(message.id, message);
   180→    },
   181→    [setActiveThread],
   182→  );
   183→
   184→  // ESC key to close thread panel
   185→  useEffect(() => {
   186→    const handleEscKey = (event: KeyboardEvent) => {
   187→      if (event.key === "Escape" && activeThreadId) {
   188→        setActiveThread(null);
   189→      }
   190→    };
   191→
   192→    window.addEventListener("keydown", handleEscKey);
   193→    return () => {
   194→      window.removeEventListener("keydown", handleEscKey);
   195→    };
   196→  }, [activeThreadId, setActiveThread]);
   197→
   198→  // WebSocket message listener
   199→  const handleNewMessage = (newMessage: Message) => {
   200→    console.log(
   201→      "📨 [DirectMessageView] 🔥 CRITICAL: New message received via WebSocket!",
   202→      {
   203→        messageId: newMessage.id,
   204→        content: newMessage.content?.substring(0, 50),
   205→        fromUser: newMessage.userId,
   206→        dmConversationId: newMessage.dmConversationId,
   207→        expectedConversationId: conversation?.id,
   208→        currentUserId,
   209→        timestamp: new Date().toISOString(),
   210→      },
   211→    );
   212→
   213→    // Try to update UI immediately
   214→    setMessages((prev) => {
   215→      console.log(
   216→        `📨 [DirectMessageView] Current message count: ${prev.length}`,
   217→      );
   218→
   219→      // Prevent duplicate messages
   220→      if (prev.some((msg) => msg.id === newMessage.id)) {
   221→        console.log(
   222→          "⚠️ [DirectMessageView] Duplicate message detected, ignoring:",
   223→          newMessage.id,
   224→        );
   225→        return prev;
   226→      }
   227→
   228→      const updated = [...prev, newMessage];
   229→      console.log(
   230→        `✅ [DirectMessageView] Message added to state. New count: ${updated.length}`,
   231→      );
   232→
   233→      // Auto scroll to bottom (only when user is already at bottom)
   234→      if (isAtBottomRef.current) {
   235→        console.log(
   236→          "📜 [DirectMessageView] User is at bottom, auto-scrolling to new message",
   237→        );
   238→        setTimeout(() => {
   239→          const messagesEndElement =
   240→            document.querySelector("#messages-end-ref");
   241→          if (messagesEndElement) {
   242→            console.log("📜 [DirectMessageView] Auto-scroll triggered");
   243→            messagesEndElement.scrollIntoView({ behavior: "smooth" });
   244→          } else {
   245→            console.log(
   246→              "⚠️ [DirectMessageView] Scroll anchor element not found",
   247→            );
   248→          }
   249→        }, 100);
   250→      } else {
   251→        console.log(
   252→          "📜 [DirectMessageView] User is not at bottom, skipping auto-scroll",
   253→        );
   254→      }
   255→
   256→      return updated;
   257→    });
   258→
   259→    console.log("✅ [DirectMessageView] Message processing completed");
   260→  };
   261→
   262→  // Get or create DM conversation
   263→  const fetchConversation = async () => {
   264→    try {
   265→      setIsLoading(true);
   266→      const response = await fetch(`/api/conversations/dm/${member.id}`);
   267→
   268→      if (!response.ok) {
   269→        throw new Error("Failed to fetch conversation");
   270→      }
   271→
   272→      const data = await response.json();
   273→      setConversation(data);
   274→
   275→      // If real conversation (non self-), clear unread count
   276→      if (!isOwnSpace && data.id && !data.id.startsWith("self-")) {
   277→        try {
   278→          // Clear unread count for this conversation
   279→          markAsRead(undefined, data.id);
   280→        } catch (markAsReadError) {
   281→          console.error("Error marking as read:", markAsReadError);
   282→          // Even if markAsRead fails, message loading is not affected
   283→        }
   284→        fetchMessages(data.id);
   285→      } else {
   286→        setIsLoading(false);
   287→      }
   288→    } catch (err) {
   289→      console.error("Error fetching conversation:", err);
   290→      setError("Failed to load conversation");
   291→      setIsLoading(false);
   292→    }
   293→  };
   294→
   295→  // Get message list
   296→  const PAGE_SIZE = 50;
   297→
   298→  const fetchMessages = async (conversationId: string) => {
   299→    try {
   300→      setIsLoading(true);
   301→      setHasMore(true);
   302→      const response = await fetch(
   303→        `/api/messages?dmConversationId=${conversationId}&limit=${PAGE_SIZE}`,
   304→      );
   305→
   306→      if (!response.ok) {
   307→        throw new Error("Failed to fetch messages");
   308→      }
   309→
   310→      const data = await response.json();
   311→      setMessages(data.reverse());
   312→      setHasMore(data.length >= PAGE_SIZE);
   313→      setIsLoading(false);
   314→    } catch (err) {
   315→      console.error("Error fetching messages:", err);
   316→      setError("Failed to load messages");
   317→      setIsLoading(false);
   318→    }
   319→  };
   320→
   321→  const fetchOlderMessages = useCallback(async () => {
   322→    if (!conversation?.id || isLoadingMore || !hasMore) return;
   323→
   324→    try {
   325→      setIsLoadingMore(true);
   326→      const container = document.getElementById("messages-scroll-container");
   327→      const prevScrollHeight = container?.scrollHeight || 0;
   328→
   329→      const response = await fetch(
   330→        `/api/messages?dmConversationId=${conversation.id}&limit=${PAGE_SIZE}&offset=${messages.length}`,
   331→      );
   332→
   333→      if (!response.ok) {
   334→        setIsLoadingMore(false);
   335→        return;
   336→      }
   337→
   338→      const data = await response.json();
   339→      setHasMore(data.length >= PAGE_SIZE);
   340→      if (data.length > 0) {
   341→        setMessages((prev) => [...data.reverse(), ...prev]);
   342→        requestAnimationFrame(() => {
   343→          if (container) {
   344→            container.scrollTop = container.scrollHeight - prevScrollHeight;
   345→          }
   346→        });
   347→      }
   348→      setIsLoadingMore(false);
   349→    } catch (err) {
   350→      console.error("Error fetching older messages:", err);
   351→      setIsLoadingMore(false);
   352→    }
   353→  }, [conversation?.id, isLoadingMore, hasMore, messages.length]);
   354→
   355→  // Initial load
   356→  useEffect(() => {
   357→    fetchConversation();
   358→  }, [member.id, isOwnSpace]);
   359→
   360→  // Handle message edit
   361→  const handleEditMessage = async (messageId: string, content: string) => {
   362→    try {
   363→      const response = await fetch(`/api/messages/${messageId}`, {
   364→        method: "PATCH",
   365→        headers: {
   366→          "Content-Type": "application/json",
   367→        },
   368→        body: JSON.stringify({ content }),
   369→      });
   370→
   371→      if (!response.ok) {
   372→        throw new Error("Failed to edit message");
   373→      }
   374→
   375→      const updatedMessage = await response.json();
   376→
   377→      // Optimistically update local message list
   378→      setMessages((prev) =>
   379→        prev.map((msg) => (msg.id === messageId ? updatedMessage : msg)),
   380→      );
   381→
   382→      console.log("✅ Message edited successfully:", messageId);
   383→    } catch (error) {
   384→      console.error("❌ Failed to edit message:", error);
   385→      throw error;
   386→    }
   387→  };
   388→
   389→  // Handle message deletion
   390→  const handleDeleteMessage = async (messageId: string) => {
   391→    try {
   392→      const response = await fetch(`/api/messages/${messageId}`, {
   393→        method: "DELETE",
   394→      });
   395→
   396→      if (!response.ok) {
   397→        throw new Error("Failed to delete message");
   398→      }
   399→
   400→      const result = await response.json();
   401→
   402→      // Optimistically update local message list (mark as deleted)
   403→      setMessages((prev) =>
   404→        prev.map((msg) =>
   405→          msg.id === messageId
   406→            ? { ...msg, isDeleted: true, deletedAt: result.data.deletedAt }
   407→            : msg,
   408→        ),
   409→      );
   410→
   411→      console.log("✅ Message deleted successfully:", messageId);
   412→    } catch (error) {
   413→      console.error("❌ Failed to delete message:", error);
   414→      throw error;
   415→    }
   416→  };
   417→
   418→  // Handle message update (from WebSocket)
   419→  const handleMessageUpdated = (updatedMessage: Message) => {
   420→    setMessages((prev) =>
   421→      prev.map((msg) => (msg.id === updatedMessage.id ? updatedMessage : msg)),
   422→    );
   423→  };
   424→
   425→  // Handle message deletion (from WebSocket)
   426→  const handleMessageDeleted = (deleteData: {
   427→    id: string;
   428→    channelId?: string;
   429→    dmConversationId?: string;
   430→    isDeleted: boolean;
   431→    deletedAt?: string;
   432→  }) => {
   433→    setMessages((prev) =>
   434→      prev.map((msg) =>
   435→        msg.id === deleteData.id
   436→          ? { ...msg, isDeleted: true, deletedAt: deleteData.deletedAt }
   437→          : msg,
   438→      ),
   439→    );
   440→  };
   441→
   442→  // WebSocket message listener
   443→  // Only start listening after conversation is loaded to ensure using real room ID
   444→  const shouldUseWebSocket =
   445→    !isOwnSpace && conversation && !conversation.id.startsWith("self-");
   446→  useWebSocketMessages({
   447→    dmConversationId: shouldUseWebSocket ? conversation.id : undefined,
   448→    currentUserId,
   449→    onNewMessage: handleNewMessage,
   450→    onMessageUpdated: handleMessageUpdated,
   451→    onMessageDeleted: handleMessageDeleted,
   452→  });
   453→
   454→  // Log WebSocket status
   455→  useEffect(() => {
   456→    if (!isOwnSpace) {
   457→      console.log(`🔌 [DirectMessageView] WebSocket status:`, {
   458→        shouldUseWebSocket,
   459→        hasConversation: !!conversation,
   460→        conversationId: conversation?.id,
   461→        memberId: member.id,
   462→      });
   463→    }
   464→  }, [shouldUseWebSocket, conversation, isOwnSpace, member.id]);
   465→
   466→  // Handle message sent
   467→  const handleMessageSent = useCallback((message?: Message) => {
   468→    // If message object is received, perform optimistic update
   469→    if (message) {
   470→      console.log(
   471→        "✅ [DirectMessageView] Message sent successfully, performing optimistic update:",
   472→        message.id,
   473→      );
   474→      setMessages((prev) => {
   475→        // Prevent duplicates
   476→        if (prev.some((msg) => msg.id === message.id)) {
   477→          console.log(
   478→            "⚠️ [DirectMessageView] Duplicate message in optimistic update, ignoring:",
   479→            message.id,
   480→          );
   481→          return prev;
   482→        }
   483→        return [...prev, message];
   484→      });
   485→    } else {
   486→      console.log(
   487→        "✅ [DirectMessageView] Message sent via API, WebSocket will handle real-time update",
   488→      );
   489→    }
   490→  }, []);
   491→
   492→  return (
   493→    <div className="flex flex-col h-full bg-background overflow-hidden">
   494→      {/* 1. Top Header - Fixed */}
   495→      <div className="flex-shrink-0">
   496→        <DMHeader member={member} currentUserId={currentUserId} />
   497→      </div>
   498→
   499→      {/* 2. Tab Navigation - Fixed */}
   500→      <div className="flex-shrink-0">
   501→        <DMTabs
   502→          isOwnSpace={isOwnSpace}
   503→          activeTab={activeTab}
   504→          onTabChange={setActiveTab}
   505→        />
   506→      </div>
   507→
   508→      {/* 3. Main content area: ensure it takes all remaining height */}
   509→      <div className="flex-1 flex flex-col min-h-0">
   510→        {/* Render different content based on activeTab */}
   511→        {activeTab === "files" &&
   512→        conversation &&
   513→        !conversation.id.startsWith("self-") ? (
   514→          <div className="flex-1 overflow-hidden">
   515→            <FileList conversationId={conversation.id} conversationType="dm" />
   516→          </div>
   517→        ) : activeTab === "files" &&
   518→          (!conversation || conversation.id.startsWith("self-")) ? (
   519→          <div className="flex-1 flex items-center justify-center text-text-secondary">
   520→            Please select a conversation to view files
   521→          </div>
   522→        ) : isOwnSpace ? (
   523→          <div className="flex-1 overflow-y-auto">
   524→            <MySpaceView member={member} currentUserId={currentUserId} />
   525→          </div>
   526→        ) : (
   527→          <>
   528→            {/* Message list and thread panel use flex layout to avoid overlapping causing event penetration */}
   529→            <div className="flex flex-1 min-h-0">
   530→              {/* Message list: must set flex-1 and min-h-0 to force fill space and support internal scrolling */}
   531→              <div className="flex-1 min-w-0 min-h-0 relative">
   532→                <MessageList
   533→                  ref={messageListRef}
   534→                  messages={messages}
   535→                  currentUserId={currentUserId}
   536→                  isLoading={isLoading}
   537→                  isLoadingMore={isLoadingMore}
   538→                  hasMore={hasMore}
   539→                  onLoadMore={fetchOlderMessages}
   540→                  className="h-full w-full"
   541→                  dmConversationId={
   542→                    conversation?.id && !conversation.id.startsWith("self-")
   543→                      ? conversation.id
   544→                      : undefined
   545→                  }
   546→                  onScrollPositionChange={handleScrollPositionChange}
   547→                  onEditMessage={handleEditMessage}
   548→                  onDeleteMessage={handleDeleteMessage}
   549→                  onThreadReply={handleThreadReply}
   550→                  onQuote={handleQuote}
   551→                />
   552→              </div>
   553→
   554→              {/* Thread panel: right slide-out panel, width 360px */}
   555→              {threadPanelOpen && (
   556→                <ThreadPanel
   557→                  isOpen={threadPanelOpen}
   558→                  onClose={closeThread}
   559→                  threadMessage={activeThreadMessage}
   560→                  currentUserId={currentUserId}
   561→                />
   562→              )}
   563→            </div>
   564→
   565→            {error && (
   566→              <div className="flex-shrink-0 p-4 bg-red-500/10 text-red-500 text-center">
   567→                {error}
   568→              </div>
   569→            )}
   570→
   571→            {/* 4. Input: use flex-shrink-0 to ensure it is pushed to the bottom, never moves up */}
   572→            <div className="flex-shrink-0 bg-background border-t relative">
   573→              {/* Top drag area */}
   574→              <div
   575→                className="absolute left-0 top-0 right-0 h-1 cursor-row-resize hover:bg-primary/50 transition-colors"
   576→                onMouseDown={handleInputDragStart}
   577→                style={{
   578→                  cursor: isResizingInput ? "row-resize" : "row-resize",
   579→                }}
   580→              />
   581→              <div
   582→                style={{
   583→                  height: `${inputHeight}px`,
   584→                  transition: isResizingInput ? 'none' : 'height 0.2s ease-out'
   585→                }}
   586→                className="p-4 overflow-hidden"
   587→              >
   588→                <DMMessageInput
   589→                  placeholder={`Message ${member.displayName}`}
   590→                  disabled={
   591→                    isLoading ||
   592→                    !conversation ||
   593→                    conversation.id.startsWith("self-")
   594→                  }
   595→                  dmConversationId={
   596→                    conversation?.id && !conversation.id.startsWith("self-")
   597→                      ? conversation.id
   598→                      : undefined
   599→                  }
   600→                  currentUserId={currentUserId}
   601→                  members={[member]}
   602→                  onMessageSent={handleMessageSent}
   603→                  quotedMessage={quotedMessage}
   604→                  onClearQuote={handleClearQuote}
   605→                />
   606→              </div>
   607→            </div>
   608→          </>
   609→        )}
   610→      </div>
   611→    </div>
   612→  );
   613→}
